import React, { useState, useEffect } from 'react';

const TaskForm = ({ onSubmit, initialData = null, onCancel }) => {
  const [formData, setFormData] = useState({
    title: '',
    description: '',
    priority: 'Medium',
    dueDate: '',
  });

  useEffect(() => {
    if (initialData) {
      setFormData({
        title: initialData.title || '',
        description: initialData.description || '',
        priority: initialData.priority || 'Medium',
        dueDate: initialData.dueDate ? new Date(initialData.dueDate).toISOString().split('T')[0] : '',
      });
    }
  }, [initialData]);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    onSubmit(formData);
    // Reset form if not editing
    if (!initialData) {
      setFormData({ title: '', description: '', priority: 'Medium', dueDate: '' });
    }
  };

  return (
    <div className="task-form-container">
      <h4 className="mb-4">{initialData ? 'Edit Task' : 'Add New Task'}</h4>
      <form onSubmit={handleSubmit}>
        <div className="mb-3">
          <label className="form-label text-muted">Task Title</label>
          <input
            type="text"
            className="form-control"
            name="title"
            value={formData.title}
            onChange={handleChange}
            placeholder="What needs to be done?"
            required
          />
        </div>

        <div className="mb-3">
          <label className="form-label text-muted">Description (Optional)</label>
          <textarea
            className="form-control"
            name="description"
            value={formData.description}
            onChange={handleChange}
            placeholder="Add details..."
            rows="3"
          ></textarea>
        </div>

        <div className="row mb-4">
          <div className="col-md-6">
            <label className="form-label text-muted">Priority</label>
            <select
              className="form-select custom-select"
              name="priority"
              value={formData.priority}
              onChange={handleChange}
            >
              <option value="Low">Low</option>
              <option value="Medium">Medium</option>
              <option value="High">High</option>
            </select>
          </div>
          <div className="col-md-6">
            <label className="form-label text-muted">Due Date (Optional)</label>
            <input
              type="date"
              className="form-control"
              name="dueDate"
              value={formData.dueDate}
              onChange={handleChange}
            />
          </div>
        </div>

        <div className="d-flex justify-content-end gap-2">
          {onCancel && (
            <button type="button" className="btn btn-secondary btn-cancel" onClick={onCancel}>
              Cancel
            </button>
          )}
          <button type="submit" className="btn-auth" style={{ width: 'auto', padding: '0.6rem 1.5rem' }}>
            <i className={`bi ${initialData ? 'bi-check2-circle' : 'bi-plus-lg'} me-2`}></i>
            {initialData ? 'Save Changes' : 'Add Task'}
          </button>
        </div>
      </form>
    </div>
  );
};

export default TaskForm;
